import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"GZIC Guide","description":"An overview of facilities at SCUT Guangzhou International Campus","frontmatter":{"lang":"en-US","title":"GZIC Guide","description":"An overview of facilities at SCUT Guangzhou International Campus","author":"Kozumi","llm_translated":true},"headers":[],"relativePath":"en/infra/gzic/map.md","filePath":"en/infra/gzic/map.md","lastUpdated":1791510705000}`),a={name:`en/infra/gzic/map.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/gzic/map.md for this page in Markdown format</div><h1 id="gzic-guide" tabindex="-1">GZIC Guide <a class="header-anchor" href="#gzic-guide" aria-label="Permalink to “GZIC Guide”">​</a></h1><h2 id="study-library-resources" tabindex="-1">Study &amp; Library Resources <a class="header-anchor" href="#study-library-resources" aria-label="Permalink to “Study &amp; Library Resources”">​</a></h2><ul><li><strong>E3 Central Library</strong>: The main library of the International Campus, equipped with study rooms and reading areas, offering a rich book collection and plenty of study seats</li><li><strong>D1 Wu Xianming Intelligent Engineering College Library</strong>: A small library inside the college</li></ul><hr><h2 id="daily-service-points" tabindex="-1">Daily Service Points <a class="header-anchor" href="#daily-service-points" aria-label="Permalink to “Daily Service Points”">​</a></h2><p>Daily services on the International Campus are concentrated <strong>near McDonald&#39;s (the area between Buildings D5 and F5)</strong>:</p><ul><li><strong>Food &amp; drink</strong>: McDonald&#39;s, Luckin Coffee, Meet Noodles, Huayuan Yunli</li><li><strong>Others</strong>: gym, print shop, hair salon</li></ul><hr><h2 id="sports-venues" tabindex="-1">Sports &amp; Venues <a class="header-anchor" href="#sports-venues" aria-label="Permalink to “Sports &amp; Venues”">​</a></h2><p>The International Campus has one gymnasium and one swimming hall. Students who know about their opening hours, booking methods, and fees are welcome to add the details.</p><h2 id="dining-convenience-facilities" tabindex="-1">Dining &amp; Convenience Facilities <a class="header-anchor" href="#dining-convenience-facilities" aria-label="Permalink to “Dining &amp; Convenience Facilities”">​</a></h2><h3 id="cafeterias" tabindex="-1">Cafeterias <a class="header-anchor" href="#cafeterias" aria-label="Permalink to “Cafeterias”">​</a></h3><ul><li><strong>F5 Cafeteria</strong>: Mixue and a baozi shop on the first floor, Cotti Coffee on the second floor</li><li><strong>D5 Cafeteria</strong>: —</li><li><strong>B2 Cafeteria</strong>: Serves Luosifen (river snail rice noodles) and grilled meat rice, and has a small campus store</li></ul><h2 id="gzic-specific-facilities" tabindex="-1">GZIC-Specific Facilities <a class="header-anchor" href="#gzic-specific-facilities" aria-label="Permalink to “GZIC-Specific Facilities”">​</a></h2><ul><li><strong>Undergraduate dormitories</strong>: concentrated in Building D5 (residential college housing)</li></ul><h2 id="sports-grounds" tabindex="-1">Sports Grounds <a class="header-anchor" href="#sports-grounds" aria-label="Permalink to “Sports Grounds”">​</a></h2><ul><li><strong>North Gate track field</strong> and <strong>Southwest Gate track field</strong>: the two track and field grounds on campus</li></ul>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};